import {Chess} from './vendor/chess.mjs';
import {Engine} from './engine.mjs';
import {fromUci,uci} from './review.mjs';
import {FutureExplorer,dailyScene,moveLabel,stepCaption,pieceNames} from './futures.mjs';
const symbols={k:'♚',q:'♛',r:'♜',b:'♝',n:'♞',p:'♟'};
export function createFutures({pause,resume,snapshot,commit}){
  document.body.insertAdjacentHTML('beforeend',`<dialog id="future-dialog" class="future-dialog" aria-labelledby="future-title"><header class="future-header"><span>棋间 · 平行棋局</span><button id="future-close" class="future-secondary">回到原棋局 ×</button></header><div class="future-intro"><p class="future-eyebrow">一个选择，展开一种可能</p><h2 id="future-title">先看见，再落子。</h2><p>试走不会改动原棋局。放心一点，直觉也需要游乐场。</p></div><div class="future-sources" role="group" aria-label="选择试走局面"><button id="future-daily" aria-pressed="true">今日灵光</button><button id="future-current" aria-pressed="false">试试我的棋局</button></div><div class="future-layout"><section><div class="future-board-top"><strong id="future-turn"></strong><button id="future-change" class="future-text">↶ 换一手试试</button></div><div class="future-board-wrap"><div id="future-board" class="board" role="group" aria-label="平行棋局试走棋盘"></div></div><div id="future-promotion" class="future-actions" hidden></div><div id="future-timeline" class="future-timeline" hidden><div class="future-actions"><button id="future-play" class="future-secondary">▶ 演给我看</button><label for="future-step">第 <span id="future-step-number">0</span> 步</label></div><input id="future-step" type="range" min="0" max="1" value="0" step="1" aria-label="拖动查看这条路线的每一步"></div><p id="future-caption" class="future-caption" role="status" aria-live="polite"></p></section><section class="future-desk"><p class="future-eyebrow" id="future-scene-label"></p><h3 id="future-scene-title"></h3><p id="future-hook"></p><div id="future-choices" class="future-choices"></div><p class="future-small">也可以直接点棋子，再点亮起的目标格。</p><div id="future-status" role="status" aria-live="polite"></div><div id="future-branches" class="future-branches" aria-label="已探索的路线"></div><button id="future-other" class="future-secondary">再给我一种可能 ↗</button><div id="future-reveal" class="future-reveal" hidden><span>啊，原来如此。</span><p id="future-insight"></p></div><button id="future-commit" class="future-primary" hidden>这一步，我真的走 ↗</button><p id="future-limit" class="future-small">参考路线由本机引擎计算，双方的后续走法都只是示例。真实对手可能另走。</p></section></div><footer class="future-footer">有些本事，是从“我再试一下”长出来的。</footer></dialog>`);
  const $=id=>document.getElementById(id),dialog=$('future-dialog'),explorer=new FutureExplorer(new Engine());
  let scene=dailyScene(),root=scene.fen,source='daily',original=null,branches=[],active=null,step=0,selected=null,promotion=null,choosing=true,busy=false,job=0,timer=null,animation=false,pendingChoice=null,showingOther=false;
  const reduced=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function status(text,error=false){$('future-status').textContent=text;$('future-status').classList.toggle('error',error);}
  function stopAnimation(){clearTimeout(timer);timer=null;animation=false;$('future-play').textContent='▶ 演给我看';}
  function cancel(){job++;explorer.cancel();stopAnimation();busy=false;showingOther=false;}
  function draw(){
    const fen=choosing?root:active?.positions[step]||root,board=new Chess(fen),legal=choosing&&selected?new Chess(root).moves({square:selected,verbose:true}):[],last=!choosing&&step>0?active?.moves[step-1]:null;
    const orientation=new Chess(root).turn(),squares=[];for(let r=0;r<8;r++)for(let c=0;c<8;c++){const rank=orientation==='w'?8-r:r+1,file=orientation==='w'?c:7-c;squares.push('abcdefgh'[file]+rank);}
    $('future-board').innerHTML=squares.map((sq,i)=>{const p=board.get(sq),light=(sq.charCodeAt(0)-97+Number(sq[1]))%2===0,can=legal.some(m=>m.to===sq),check=p?.type==='k'&&p.color===board.turn()&&board.isCheck();return `<button class="square ${light?'light':'dark'} ${p?'occupied':''} ${can?'legal':''} ${selected===sq?'selected':''} ${last&&(last.from===sq||last.to===sq)?'last-move':''} ${check?'in-check':''}" data-future-square="${sq}" aria-label="${sq}${p?' '+(p.color==='w'?'白':'黑')+pieceNames[p.type]:' 空格'}${can?' 可走':''}" ${!choosing?'disabled':''}>${p?`<span class="piece ${p.color==='w'?'white':'black'}" aria-hidden="true">${symbols[p.type]}</span>`:''}${i%8===0?`<span class="coordinate rank">${sq[1]}</span>`:''}${i>=56?`<span class="coordinate file">${sq[0]}</span>`:''}</button>`;}).join('');
    $('future-turn').textContent=choosing?(new Chess(root).turn()==='w'?'白方':'黑方')+'走 · 这次可以先试':step===0?'同一个起点':active.moves[step-1].san.endsWith('#')?'原来，这里就能结束':'这条路线 · 第 '+step+' 步';
    $('future-caption').textContent=choosing?'点一枚棋子，把“如果”走出来。':step?stepCaption(active.moves[step-1]):'把时间往前拨，看看刚才那一步带来了什么。';
    $('future-timeline').hidden=!active||choosing;$('future-step').max=String(active?.moves.length||1);$('future-step').value=String(step);$('future-step-number').textContent=String(step);
    $('future-promotion').hidden=!promotion;$('future-promotion').innerHTML=promotion?['q','r','b','n'].map(p=>`<button class="future-secondary" data-future-promote="${p}">升变为${pieceNames[p]}</button>`).join(''):'';
    $('future-other').disabled=busy||new Chess(root).isGameOver();$('future-other').textContent=showingOther?'正在寻找另一种可能…':'再给我一种可能 ↗';
    $('future-commit').hidden=source!=='current'||!original?.canCommit||!active||choosing||busy;
    $('future-branches').innerHTML=branches.map((b,i)=>`<button class="future-branch ${active===b?'active':''}" aria-pressed="${active===b}" data-future-branch="${i}"><span>路线 ${String.fromCharCode(65+i)}</span><strong>${b.label}</strong><small>${b.terminal==='mate'?'看见了将死':b.moves.length+' 步参考路线'}${b.depth?' · 深度 '+b.depth:''}</small></button>`).join('');
    const learned=source==='daily'&&branches.some(b=>b.choice===scene.choices[1]);$('future-reveal').hidden=!learned;$('future-insight').textContent=scene.discovery;
  }
  function choose(){cancel();selected=null;promotion=null;choosing=true;step=0;pendingChoice=null;status('原棋局还在原处。换一个念头，再看一次。');draw();}
  function animate(){if(!active||choosing)return;stopAnimation();if(reduced()){step=active.moves.length;draw();return;}animation=true;step=0;$('future-play').textContent='Ⅱ 暂停';draw();const tick=()=>{if(!animation||!dialog.open)return;step++;draw();if(step>=active.moves.length){stopAnimation();return;}timer=setTimeout(tick,1100);};timer=setTimeout(tick,450);}
  async function trial(choice){
    cancel();const token=job;selected=null;promotion=null;pendingChoice=choice;choosing=true;status('正在为这一步展开参考路线…');busy=true;draw();
    try{const result=await explorer.explore(root,choice);if(token!==job||!dialog.open)return;const existing=branches.find(b=>b.choice===result.choice);active=existing||result;if(!existing){branches.push(result);if(branches.length>6)branches.shift();}choosing=false;step=0;status(result.summary);busy=false;draw();animate();}
    catch(e){if(token!==job)return;status('这条路线暂时没算出来。可以换一步，或再点一次原来的走法。',true);}
    finally{if(token===job){busy=false;draw();}}
  }
  function setup(kind){cancel();source=kind;scene=dailyScene();root=kind==='current'?original.fen:scene.fen;branches=[];active=null;step=0;selected=null;promotion=null;choosing=true;pendingChoice=null;$('future-daily').setAttribute('aria-pressed',String(kind==='daily'));$('future-current').setAttribute('aria-pressed',String(kind==='current'));
    $('future-scene-label').textContent=kind==='daily'?scene.day+' · 每日一眼':'你的局面 · 当下这一秒';$('future-scene-title').textContent=kind==='daily'?scene.title:'把你的直觉，先活一遍。';$('future-hook').textContent=kind==='daily'?scene.hook:'用自己的棋局比较几种选择。棋盘上的选择越具体，看到的差别就越清楚。';
    $('future-choices').innerHTML=kind==='daily'?scene.choices.map(code=>`<button class="future-choice" data-future-choice="${code}"><span>试试</span><strong>${moveLabel(root,code)}</strong><span>↗</span></button>`).join(''):'';
    status(new Chess(root).isGameOver()?'这个局面已经结束。切到「今日灵光」可以继续探索。':kind==='current'&&!original.canCommit?'这个局面可以试走；回放或对手回合的试走不能直接落入原局。':'不用先证明自己会下棋。点一步，就有一条路。');draw();
  }
  $('future-board').onclick=e=>{const cell=e.target.closest('[data-future-square]');if(!cell||!choosing)return;const sq=cell.dataset.futureSquare,b=new Chess(root),matches=selected?b.moves({square:selected,verbose:true}).filter(m=>m.to===sq):[];if(matches.length){if(matches.some(m=>m.promotion)){promotion={from:selected,to:sq};draw();}else trial(selected+sq);return;}promotion=null;const p=b.get(sq);selected=p?.color===b.turn()&&selected!==sq?sq:null;draw();if(selected)$('future-board').querySelector(`[data-future-square="${selected}"]`)?.focus({preventScroll:true});};
  $('future-promotion').onclick=e=>{const p=e.target.dataset.futurePromote;if(p&&promotion)trial(promotion.from+promotion.to+p);};
  $('future-choices').onclick=e=>{const b=e.target.closest('[data-future-choice]');if(b)trial(b.dataset.futureChoice);};
  $('future-branches').onclick=e=>{const b=e.target.closest('[data-future-branch]');if(!b)return;cancel();active=branches[+b.dataset.futureBranch];choosing=false;step=active.moves.length;selected=null;promotion=null;status(active.summary);draw();};
  $('future-other').onclick=async()=>{if(busy)return;if(source==='daily'){trial(scene.choices.find(c=>c!==active?.choice)||scene.choices[0]);return;}cancel();const token=job;busy=true;showingOther=true;status('看看引擎还想到了哪一步…');draw();try{const candidate=await explorer.suggest(root,active?.choice);if(token!==job||!dialog.open)return;await trial(candidate.choice);if(!candidate.preferred)status('你刚才已选中了引擎首选。这里换一个合法走法作对照，并非次佳排名。');}catch{if(token===job)status('暂时没找到参考路线。你仍可以直接点棋子试走。',true);}finally{if(token===job){busy=false;showingOther=false;draw();}}};
  $('future-play').onclick=()=>animation?stopAnimation():animate();$('future-step').oninput=()=>{stopAnimation();step=Number($('future-step').value);draw();};$('future-change').onclick=choose;$('future-daily').onclick=()=>setup('daily');$('future-current').onclick=()=>setup('current');
  $('future-commit').onclick=()=>{if(!active||source!=='current'||!original.canCommit)return;try{commit(root,fromUci(active.choice));dialog.close();}catch(e){status(e.message,true);}};
  $('future-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{cancel();resume();});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAnimation();});window.addEventListener('pagehide',cancel);
  function open(kind='daily'){if(dialog.open)return;original=snapshot();pause();setup(kind);dialog.showModal();}
  $('future-open').onclick=()=>open();$('future-live').onclick=()=>open('current');return {open};
}
